SELECT url, header_json
FROM bt_service_gateway
WHERE status_cd = '00A'
  AND platform_id = #{platformId}
  AND env_code = #{envCode}
  AND tenant_id = #{tenantId}

SELECT 
FROM bt_service_gateway a
WHERE a.status_cd = '00A'
AND a.platform_id = #{platformId}
AND a.tenant_id = #{tenantId}

SELECT ,
b.platform_name,
b.platform_code
FROM bt_service_gateway a
LEFT JOIN bt_service_platform b ON a.platform_id = b.platform_id AND a.tenant_id = b.tenant_id
WHERE a.status_cd = '00A'
  AND b.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.env_code = #{envCode}
  AND a.url = #{url}
